	src: PdfImageSrc;
	/** @default 'default' */
	variant?: PdfImageVariant;
	width?: number | string;
	height?: number | string;
	fit?: PdfImageFit;
	/** @default '50% 50%' */
	position?: string;
	caption?: string;
	aspectRatio?: number;
	borderRadius?: number;
	/** @default true */
	noWrap?: boolean;
	style?: Style;
}

